using System;
using UnityEngine.SceneManagement;

namespace Astrea;

public static class GameScenesUtils
{
	public const int SPLASH_SCREEN = 1;

	public const int INTRO_CUTSCENE = 2;

	public const int MAIN_MENU = 3;

	public const int BATTLE_SCENE = 4;

	public const string BOOTSTRAP_NAME = "Bootstrap";

	public const string SPLASH_SCREEN_NAME = "SplashScreen";

	public const string INTRO_CUTSCENE_NAME = "IntroCutscene";

	public const string MAIN_MENU_NAME = "MainMenu";

	public const string BATTLE_SCENE_NAME = "BattleScene";

	public static bool IsBootstrapScene()
	{
		return SceneManager.GetActiveScene().name == "Bootstrap";
	}

	public static bool IsBattleScene()
	{
		return SceneManager.GetActiveScene().name == "BattleScene";
	}

	public static bool IsSplashScreen()
	{
		return SceneManager.GetActiveScene().name == "SplashScreen";
	}

	public static bool IsMainMenu()
	{
		return SceneManager.GetActiveScene().name == "MainMenu";
	}

	public static bool IsIntroCutscene()
	{
		return SceneManager.GetActiveScene().name == "IntroCutscene";
	}

	public static string GetSceneNameFromSceneIndex(int sceneIndex)
	{
		return sceneIndex switch
		{
			1 => "SplashScreen", 
			2 => "IntroCutscene", 
			3 => "MainMenu", 
			4 => "BattleScene", 
			_ => throw new ArgumentException($"Asked for SceneIndex:{sceneIndex} but it isn't configure! Review this code!"), 
		};
	}
}
